INSERT INTO `products` VALUES (3470,'MLPF3B/A','MLPF3B/A','apple-iphone-13-155-cm-61-dual-sim-ios-15-5g-128-gb-black-4-and-more-iphone-bar-128gb-to-256gb-5g-ios-15-ios-black-dual-camera-dual-sim-13-mlpf3ba','Apple iPhone 13 128GB - Midnight','<b>iPhone 13</b><br><b>Your new superpower.</b><br><br>Our most advanced dualâ€‘camera system ever. Get up to 47% better low-light performance.<br><br>Cinematic mode adds shallow depth of field automatically. You can also shift focus after you shoot.<br><br>Up to 19 hours of video playback. A big leap in battery life.<br><br>More powerful than ever before with the new A15 Bionic chip and superfast 5G.<br><br>Ceramic Shield is tougher than any smartphone glass. And you get dust, spill, and water resistance.',734,'https://images.shopcdn.co.uk/56/0f/560f0fe1798acae73c1f95f3ddac1e33/2000x2000/webp/resize?quality=80&compression=80','[{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/56\\/0f\\/560f0fe1798acae73c1f95f3ddac1e33\\/2000x2000\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/fd\\/ff\\/fdff9c1dd37570867d909fe85cbec3fb\\/300x137\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/bf\\/33\\/bf33bac63f03fa922cc596327e63dcc9\\/2000x2000\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/c8\\/d7\\/c8d7b91f2d1a25d5d1a3b3feb2a18e3a\\/2000x2000\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/39\\/5b\\/395be5eb7661b4249e9833c7620f0e75\\/2000x2000\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/48\\/1e\\/481eaa5e34b32df1e8cdc673e2346e1e\\/2000x2000\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/ff\\/fb\\/fffb8d13781a5e00c6405e024b5ec5c9\\/178x200\\/webp\\/resize?quality=80&compression=80\"}]','{\"code\":1,\"cost\":350.95,\"net\":421.14}',2,44,2823,22,'2025-09-01 12:30:39','2025-09-03 13:40:08','2025-09-02 13:43:53','2025-09-02 13:43:53'),(4175,'8175','8175','doro-8100-155-cm-61-dual-sim-android-11-go-edition-4g-usb-type-c-2-gb-32-gb-3000-mah-grey','Doro 8100 15.5 cm (6.1\") Single SIM Android 11 Go Edition 4G USB Type-C 2 GB 32 GB 3000 mAh Grey','<b>The easy to use, easy to love smartphone</b><br>If you want an easy to use smartphone that makes staying connected with family and friends both fun and reassuring, then you\'ll love the Doro 8100. Conversations are clearer with Doro\'s optimized sound quality, and our intuitive interface simplifies everything you want to do. Three lenses and a simplified camera menu make it easy to capture spectacular images, including great portraits and low light shots. And two pre-installed apps enable trusted contacts to provide support if you need it. With the TeamViewer app, a person you invite can access and assist you with your phone directly from their own device. And the Response by Doro app, once set up, can send alerts and connect you with family or friends with one press of the assistance button, e.g. if you should fall and need someone\'s help.',26,'https://images.shopcdn.co.uk/a7/2a/a72a747e800ddbd0a4eb4a377646e755/1248x1623/webp/resize?quality=80&compression=80','[{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/a7\\/2a\\/a72a747e800ddbd0a4eb4a377646e755\\/1248x1623\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/f8\\/5f\\/f85f6db3e90de868b907fe271f00ae45\\/300x137\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/cc\\/4c\\/cc4c528bad999de8c03ce277bea7452d\\/2000x1334\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/63\\/97\\/6397f297f5e76bc3f08b15cf4261898f\\/1825x1943\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.shopcdn.co.uk\\/6c\\/8a\\/6c8a7429acb92db6110c775f094b4074\\/2000x1334\\/webp\\/resize?quality=80&compression=80\"},{\"url\":\"https:\\/\\/images.